<?php
declare(strict_types=1);
$root=dirname(__DIR__);$configFile=$root.'/app/config.php';$lockFile=$root.'/storage/installed.lock';$done=file_exists($configFile)&&file_exists($lockFile);$errors=[];$success=false;

if(!$done && ($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    $dbHost=trim((string)($_POST['db_host']??'localhost'));$dbPort=(int)($_POST['db_port']??3306);$dbName=trim((string)($_POST['db_name']??''));$dbUser=trim((string)($_POST['db_user']??''));$dbPass=(string)($_POST['db_pass']??'');
    $baseUrl=rtrim(trim((string)($_POST['base_url']??'https://www.waithakandegwa.com')),'/');$contact=trim((string)($_POST['contact_email']??''));$adminName=trim((string)($_POST['admin_name']??'Waithaka Ndegwa'));$adminEmail=trim((string)($_POST['admin_email']??''));$adminPass=(string)($_POST['admin_password']??'');
    if(!preg_match('~^https://~i',$baseUrl))$errors[]='Use an HTTPS base URL.';
    if($dbName===''||$dbUser==='')$errors[]='Database name and database user are required.';
    if(!filter_var($contact,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid contact recipient email.';
    if(!filter_var($adminEmail,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid Writer login email.';
    if(strlen($adminPass)<12)$errors[]='Use a Writer password of at least 12 characters.';
    $required=['pdo_mysql','curl','mbstring','openssl','dom','fileinfo'];foreach($required as $ext)if(!extension_loaded($ext))$errors[]='Missing required PHP extension: '.$ext;
    if(!$errors){
        try{
            $dsn=sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$dbHost,$dbPort,$dbName);$pdo=new PDO($dsn,$dbUser,$dbPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
            $schema=file_get_contents($root.'/app/schema.sql');if($schema===false)throw new RuntimeException('Could not read database schema.');
            foreach(preg_split('/;\s*(?:\r?\n|$)/',$schema) as $sql){$sql=trim($sql);if($sql!=='')$pdo->exec($sql);}
            $hash=password_hash($adminPass,PASSWORD_DEFAULT);$st=$pdo->prepare('INSERT INTO users(name,email,password_hash,is_active) VALUES(?,?,?,1) ON DUPLICATE KEY UPDATE name=VALUES(name),password_hash=VALUES(password_hash),is_active=1');$st->execute([$adminName,strtolower($adminEmail),$hash]);
            $insert=$pdo->prepare('INSERT INTO settings(setting_key,setting_value,is_secret) VALUES(?,?,0) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),is_secret=0');
            $defaults=[
              'contact.recipient'=>$contact,'mail.from'=>'noreply@'.preg_replace('/^www\./','',parse_url($baseUrl,PHP_URL_HOST)?:'waithakandegwa.com'),
              'google.ga4'=>'G-WCKVHN823V','google.search_verification'=>'','openai.model'=>'gpt-5.4-mini','mpesa.environment'=>'sandbox','mpesa.transaction_type'=>'CustomerPayBillOnline','pesapal.environment'=>'sandbox','pesapal.ipn_id'=>'','paypal.environment'=>'sandbox','recaptcha.site_key'=>''
            ];foreach($defaults as $k=>$v)$insert->execute([$k,$v]);
            $appKey=bin2hex(random_bytes(32));
            $config="<?php\nreturn ".var_export([
              'app_env'=>'production','base_url'=>$baseUrl,'force_canonical'=>true,'timezone'=>'Africa/Nairobi','app_key'=>$appKey,
              'db'=>['host'=>$dbHost,'port'=>$dbPort,'name'=>$dbName,'user'=>$dbUser,'pass'=>$dbPass,'charset'=>'utf8mb4']
            ],true).";\n";
            if(file_put_contents($configFile,$config,LOCK_EX)===false)throw new RuntimeException('Could not write app/config.php. Check directory permissions.');@chmod($configFile,0640);
            if(file_put_contents($lockFile,'Installed '.date(DATE_ATOM)."\n",LOCK_EX)===false)throw new RuntimeException('Could not write installation lock.');@chmod($lockFile,0640);
            $done=true;$success=true;
        }catch(Throwable $e){$errors[]=$e->getMessage();}
    }
}
$checks=[
 'PHP 8.1+'=>version_compare(PHP_VERSION,'8.1.0','>='),'PDO MySQL'=>extension_loaded('pdo_mysql'),'cURL'=>extension_loaded('curl'),'mbstring'=>extension_loaded('mbstring'),'OpenSSL'=>extension_loaded('openssl'),'DOM'=>extension_loaded('dom'),'Fileinfo'=>extension_loaded('fileinfo'),'Writable app folder'=>is_writable($root.'/app'),'Writable storage folder'=>is_writable($root.'/storage')
];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Install · Waithaka Ndegwa</title><style>:root{--blue:#2b54b3;--green:#337533;--ink:#17202b;--line:#e2e3e5;--paper:#f7f7f4}*{box-sizing:border-box}body{font-family:ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:var(--paper);color:var(--ink);margin:0}.wrap{width:min(920px,calc(100% - 30px));margin:50px auto}.brand{display:flex;align-items:center;gap:12px;margin-bottom:24px}.brand img{width:54px;height:54px}.brand strong{font-size:1.2rem}.card{background:#fff;border:1px solid var(--line);border-radius:20px;padding:30px;box-shadow:0 18px 50px rgba(20,25,30,.06)}h1{font-family:Georgia,serif;font-size:2.8rem;margin:.1em 0}.lead{color:#606a73}.checks{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:22px 0}.check{font-size:.82rem;padding:9px;border-radius:9px;background:#f2f3f4}.check.ok{background:#edf7ed;color:#2f6733}.check.bad{background:#fff0ef;color:#8a322c}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.field{display:flex;flex-direction:column;gap:6px}.field.full{grid-column:1/-1}.field label{font-size:.8rem;font-weight:800}.field input{padding:11px 12px;border:1px solid #cfd2d5;border-radius:9px;font:inherit}.sep{border:0;border-top:1px solid var(--line);margin:26px 0}.btn{border:0;background:var(--blue);color:#fff;border-radius:999px;padding:12px 18px;font-weight:800;font:inherit;cursor:pointer}.error{background:#fff0ef;color:#8a322c;border-radius:10px;padding:10px 12px;margin:8px 0}.success{background:#edf7ed;color:#2f6733;border-radius:10px;padding:14px}.small{font-size:.8rem;color:#6a737c}@media(max-width:700px){.checks,.grid{grid-template-columns:1fr}.field.full{grid-column:auto}.card{padding:20px}}</style></head><body><div class="wrap"><div class="brand"><img src="../assets/images/icon.png" alt=""><div><strong>Waithaka Ndegwa</strong><div class="small">First installation</div></div></div><div class="card"><?php if($done):?><h1>Installation complete.</h1><div class="success"><?= $success?'The website, database and Writer account are ready.':'This installation is already locked.' ?></div><p>Continue to the focused publishing area. You can configure OpenAI, Google, M-Pesa, Pesapal and PayPal later under <strong>Writer → Settings</strong>.</p><p><a class="btn" href="../write">Open Writer →</a></p><p class="small">For additional security, you may delete the <code>/install</code> directory after confirming the site works. Reinstallation is blocked by the installation lock.</p><?php else:?><h1>Install the site.</h1><p class="lead">Create the MySQL database and user in cPanel first, then enter those credentials below. No cron jobs are required.</p><?php foreach($errors as $error):?><div class="error"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endforeach;?><div class="checks"><?php foreach($checks as $label=>$ok):?><div class="check <?=$ok?'ok':'bad'?>"><?=$ok?'✓':'×'?> <?=htmlspecialchars($label)?></div><?php endforeach;?></div><form method="post"><h3>Website</h3><div class="grid"><div class="field full"><label>Base URL</label><input name="base_url" value="<?=htmlspecialchars($_POST['base_url']??'https://www.waithakandegwa.com')?>" required></div><div class="field"><label>Contact recipient email</label><input name="contact_email" type="email" value="<?=htmlspecialchars($_POST['contact_email']??'')?>" required></div></div><hr class="sep"><h3>MySQL database</h3><div class="grid"><div class="field"><label>Host</label><input name="db_host" value="<?=htmlspecialchars($_POST['db_host']??'localhost')?>" required></div><div class="field"><label>Port</label><input name="db_port" type="number" value="<?=htmlspecialchars($_POST['db_port']??'3306')?>" required></div><div class="field"><label>Database name</label><input name="db_name" value="<?=htmlspecialchars($_POST['db_name']??'')?>" required></div><div class="field"><label>Database user</label><input name="db_user" value="<?=htmlspecialchars($_POST['db_user']??'')?>" required></div><div class="field full"><label>Database password</label><input name="db_pass" type="password"></div></div><hr class="sep"><h3>Writer login</h3><div class="grid"><div class="field"><label>Name</label><input name="admin_name" value="<?=htmlspecialchars($_POST['admin_name']??'Waithaka Ndegwa')?>" required></div><div class="field"><label>Email</label><input name="admin_email" type="email" value="<?=htmlspecialchars($_POST['admin_email']??'')?>" required></div><div class="field full"><label>Password · minimum 12 characters</label><input name="admin_password" type="password" minlength="12" required></div></div><p style="margin-top:24px"><button class="btn" type="submit">Install website →</button></p></form><?php endif;?></div></div></body></html>
